import 'dart:math';
import 'package:flutter_test/flutter_test.dart';
import 'package:ludo_dz/game/ludo_rules.dart';
import 'package:ludo_dz/models/game_models.dart';
void main() { group('Ludo rules', () { test('valid player counts', () { expect(LudoRules.newGame(playerCount: 2).players, hasLength(2)); expect(LudoRules.newGame(playerCount: 3).players, hasLength(3)); expect(LudoRules.newGame(playerCount: 4).players, hasLength(4)); expect(() => LudoRules.newGame(playerCount: 1), throwsArgumentError); }); test('six exits home and grants turn', () { final result = LudoRules.move(LudoRules.newGame(playerCount: 2).copyWith(dice: 6), 0); expect(result.state.tokens['p0']![0].progress, 0); expect(result.state.currentPlayer, 0); }); test('overshoot is illegal', () { final state = GameState(players: [const PlayerState(id: 'p0', name: 'A', color: PlayerColor.red)], tokens: {'p0': [const TokenState(id: 0, progress: 56), const TokenState(id: 1), const TokenState(id: 2), const TokenState(id: 3)]}, currentPlayer: 0, dice: 2); expect(LudoRules.legalTokenIds(state, 2), isEmpty); }); test('safe cells and dice bounds', () { expect(LudoRules.safeCells, contains(0)); for (var i = 0; i < 20; i++) expect(LudoRules.roll(Random()), inInclusiveRange(1, 6)); }); }); }
